#define main original_main
#include "search.cpp"
#undef main
struct M{G g;int n;vector<array<int,3>>nb;vector<array<int,4>>bd;M(G const&h,vector<pair<int,int>>cuts):g(h),n(h.n){for(auto [u,v]:cuts){int x=g.n++,y=g.n++;g.del(u,v);g.add(u,x);g.add(v,y);bd.push_back({u,v,x,y});}for(int i=0;i<n;i++){array<int,3>t;U m=g.a[i];for(int&v:t){v=lo(m);m&=m-1;}nb.push_back(t);}}};
struct MS{M const&p;array<int,32>c{};MS(M const&p):p(p){c.fill(-1);}bool valid(){for(int i=0;i<p.n;i++){U m=0;int un=0;for(int u:p.nb[i])if(c[u]<0)un++;else{if(c[u]==c[i])return false;m|=1u<<c[u];}if(pc(m)>2||pc(m)+un<2)return false;}for(auto b:p.bd){U m=0;for(int u:b)if(c[u]>=0)m|=1u<<c[u];if(pc(m)==4)return false;}return true;}
 bool dfs(int left,int used){if(!left)return true;int v=-1,best=-1;for(int i=0;i<p.g.n;i++)if(c[i]<0){int s=0;for(U m=p.g.a[i];m;m&=m-1){int j=lo(m);s+=4*(c[j]>=0);for(U z=p.g.a[j];z;z&=z-1)s+=c[lo(z)]>=0;}if(s>best)best=s,v=i;}for(int x=0;x<min(4,used+1);x++){c[v]=x;if(valid()&&dfs(left-1,max(used,x+1)))return true;c[v]=-1;}return false;}bool solve(){return dfs(p.g.n,0);}};
struct MT{M const&p;array<int,32>w;MT(M const&p):p(p){}bool valid(UF const&f,vector<pair<int,int>>const&neq){for(auto[a,b]:neq)if(f.r(a)==f.r(b))return false;return true;}
 bool dfs(UF f,vector<pair<int,int>>neq,U rem){if(!rem){for(int i=0;i<p.g.n;i++)w[i]=f.r(i);return true;}int v=-1;U opt=0;for(U m=rem;m;m&=m-1){int i=lo(m);U o=0;for(int j=0;j<3;j++){int a=p.nb[i][(j+1)%3],b=p.nb[i][(j+2)%3],c=p.nb[i][j];UF h=f;h.join(a,b);if(h.r(a)!=h.r(c)&&valid(h,neq))o|=1u<<j;}if(!o)return false;if(v<0||pc(o)<pc(opt)){v=i;opt=o;if(pc(o)==1)break;}}for(U m=opt;m;m&=m-1){int j=lo(m),a=p.nb[v][(j+1)%3],b=p.nb[v][(j+2)%3],c=p.nb[v][j];UF h=f;h.join(a,b);auto nn=neq;nn.emplace_back(a,c);if(dfs(h,nn,rem^(1u<<v)))return true;}return false;}bool solve(){return dfs(UF(),p.g.edges(),(1u<<p.n)-1);}};
int main(int argc,char**argv){int maxn=argc>1?atoi(argv[1]):16,maxcuts=argc>2?atoi(argv[2]):2;int count=0,fail4=0,failAll=0;for(int n=4;n<=maxn;n+=2){ifstream file("exceptions_"+to_string(n)+".txt");string s,tag;while(file>>tag>>s){assert(tag=="impossible");G g=parse(s);auto e=g.edges();vector<pair<int,int>>cut;function<bool(int,int)>gen=[&](int i,int left){if(!left){M p(g,cut);MS f(p);count++;if(f.solve())return false;fail4++;MT t(p);if(t.solve()){cout<<"HIT "<<s;for(auto[u,v]:cut)cout<<" "<<u<<","<<v;cout<<" colors";for(int i=0;i<p.g.n;i++)cout<<" "<<t.w[i];cout<<endl;return true;}failAll++;return false;}for(int j=i;j+left<=(int)e.size();j++){cut.push_back(e[j]);if(gen(j+1,left-1))return true;cut.pop_back();}return false;};for(int k=1;k<=maxcuts;k++)if(gen(0,k))return 0;}cerr<<"n="<<n<<" tests="<<count<<" fail4="<<fail4<<" failAll="<<failAll<<endl;}cout<<"NO HIT"<<endl;}
